insert into public.docs(path,data) values ('noticiasDia/2026-11-19','{"itens": [{"c": "Algodão", "d": "2026-11-19", "f": "Folha Agrícola", "t": "Pluma sobe no mercado interno, mas segue aquém da paridade de exportação", "r": "Cotações domésticas do algodão avançaram, porém continuam abaixo do nível que tornaria a exportação equivalente, segundo análise de mercado.", "u": "https://folhaagricola.com.br/2026/11/19/algodao-precos-internos-avancam-mas-seguem-abaixo-da-paridade-de-exportacao/"}, {"c": "Algodão", "d": "2026-11-19", "f": "NX1", "t": "Brasil projeta 4,14 milhões de t de algodão em 2026/27 enquanto oferta global recua", "r": "Produção brasileira estimada em 4,14 milhões de toneladas na próxima safra vai na direção oposta à queda esperada no mundo.", "u": "https://nx1.com.br/2026/11/19/algodao-brasil-deve-produzir-414-milhoes-de-toneladas-em-2026-27-na-contramao-da-queda-global/"}, {"c": "Algodão", "d": "2026-11-19", "f": "O Correio News", "t": "Algodão nacional tenta se adequar às exigências do mercado europeu", "r": "Setor cotonicultor brasileiro busca espaço dentro das novas regras da União Europeia para manter e ampliar acesso ao bloco.", "u": "https://www.ocorreionews.com.br/2026/11/19/algodao-brasileiro-busca-espaco-nas-regras-da-europa/"}, {"c": "Câmbio", "d": "2026-11-19", "f": "InfoMoney", "t": "Dólar avança 1,1% e encerra em R$ 5,93 mesmo com leilão do BC", "r": "Moeda americana subiu 1,1% e fechou a R$ 5,93, pressionada pelo temor fiscal, apesar da intervenção do Banco Central.", "u": "https://www.infomoney.com.br/mercados/dolar-hoje-abertura-fechamento-comercial-turismo-19112026/"}, {"c": "Câmbio", "d": "2026-11-19", "f": "Tribuna do Sertão", "t": "Atuação do Banco Central não contém dólar, que chega a R$ 5,93", "r": "Intervenção do BC não foi suficiente para aliviar o estresse; preocupação fiscal levou o dólar a R$ 5,93.", "u": "https://www.tribunadosertao.com.br/geral/2026/11/19/1026112-intervencao-do-bc-nao-alivia-estresse-e-dolar-vai-a-r-593-co